  Relation result;
  while (auto tuple=cursor.next()) {
    check(tuple->layout().same_token(cursor.layout()),"factor result layout token");
    check(result.insert(crown::storage::export_row(tuple->values())).second,"duplicate factor key");
  }
  return result;
}

